def _endpoints_from_canonical_edge_id(edge_id: str) -> tuple[str, str] | None:
    raw = str(edge_id)
    if "->" not in raw:
        return None
    source, target = raw.split("->", 1)
    if not source or not target:
        return None
    return source, target

